import{_ as a,o as i,c as t,a8 as r}from"./chunks/framework.BG9kL4Xs.js";const p=JSON.parse('{"title":"Developer docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-plugin/developer-docs.md","filePath":"content/plugins/bcew-plugin/developer-docs.md"}'),n={name:"content/plugins/bcew-plugin/developer-docs.md"};function o(l,e,d,s,c,m){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="developer-docs" tabindex="-1">Developer docs <a class="header-anchor" href="#developer-docs" aria-label="Permalink to “Developer docs”">​</a></h1><p>Implementation details for the features documented in <a href="./user-docs">User docs</a>.</p><h2 id="in-page-navigation" tabindex="-1">In-Page Navigation <a class="header-anchor" href="#in-page-navigation" aria-label="Permalink to “In-Page Navigation”">​</a></h2><ul><li>Scans H2 elements and adds IDs if missing, using the heading slug and index.</li><li>Example generated ID: <code>section-getting-started-0</code> for “Getting Started”.</li><li>Uses theme root padding variables; no user configuration is required.</li></ul><h2 id="navigation-block" tabindex="-1">Navigation Block <a class="header-anchor" href="#navigation-block" aria-label="Permalink to “Navigation Block”">​</a></h2><p>If both visibility settings are disabled, the block still renders as a safety fallback to avoid hiding site navigation entirely. To truly hide it, use theme visibility controls or CSS.</p><h2 id="breadcrumb-block" tabindex="-1">BreadCrumb Block <a class="header-anchor" href="#breadcrumb-block" aria-label="Permalink to “BreadCrumb Block”">​</a></h2><ul><li>Dynamic server-side rendering is implemented in PHP in <code>render.php</code>; breadcrumb HTML is not stored in post content.</li><li>RTL-compatible styles are provided by a separate compiled CSS file.</li></ul><h3 id="styling-and-customization" tabindex="-1">Styling and customization <a class="header-anchor" href="#styling-and-customization" aria-label="Permalink to “Styling and customization”">​</a></h3><ul><li>Target wrapper selector: <code>.dswp-block-breadcrumb__container</code>.</li><li>Separator element: <code>.dswp-breadcrumb-separator</code>.</li><li>Provide overrides in a theme stylesheet or a global style variation.</li><li>RTL adjustments are handled by generated <code>style-index-rtl.css</code>.</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h3><p>Dynamic rendering avoids recalculating trails client-side. Markup is minimal and styles are precompiled.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h3><p>There is no built-in schema markup; it can be added in a theme if desired.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related documentation”">​</a></h2><ul><li><a href="./user-docs">User docs</a> for site-author and administrator instructions.</li><li><a href="./index">Plugin overview</a>.</li></ul>',16)])])}const u=a(n,[["render",o]]);export{p as __pageData,u as default};
